sys_ui_page.client_script:
var erTimer = null, erStart = new Date().getTime(), erLast = '';

(function erBegin() {
  var enc = gel('er_encounter').value;
  var ga = new GlideAjax('x_2206627_er_tri_0.ERTriageRunAjax');
  ga.addParam('sysparm_name', 'start');
  ga.addParam('sysparm_encounter', enc);
  ga.getXMLAnswer(function(answer) {
    var r = JSON.parse(answer);
    if (!r.ok) { erFail(r.error); return; }
    erTimer = setInterval(erPoll, 2000);
    erPoll();
  });
})();

function erPoll() {
  gel('er_elapsed').innerHTML = Math.round((new Date().getTime() - erStart) / 1000);
  var ga = new GlideAjax('x_2206627_er_tri_0.ERTriageRunAjax');
  ga.addParam('sysparm_name', 'status');
  ga.addParam('sysparm_encounter', gel('er_encounter').value);
  ga.getXMLAnswer(function(answer) {
    var r = JSON.parse(answer);
    if (r.message && r.message != erLast) {
      var log = gel('er_log');
      var prev = log.querySelector('.current');
      if (prev) prev.className = 'er-step';
      var d = document.createElement('div');
      d.className = 'er-step current';
      d.appendChild(document.createTextNode('\u2022 ' + r.message));
      log.appendChild(d);
      gel('er_msg').innerHTML = '';
      gel('er_msg').appendChild(document.createTextNode(r.message));
      erLast = r.message;
    }
    if (r.status == 'done') erDone(r);
    else if (r.status == 'failed') erFail(r.message);
    else if ((new Date().getTime() - erStart) > 180000) erFail('Still running after 3 minutes. Check the encounter later.');
  });
}

function erDone(r) {
  clearInterval(erTimer);
  gel('er_running').style.display = 'none';
  var box = gel('er_done');
  box.style.display = 'block';
  var esc = function(s) { var t = document.createElement('div'); t.appendChild(document.createTextNode(s || '')); return t.innerHTML; };
  box.innerHTML =
    '<p style="font-size:16px;"><b>Suggested ESI: ' + esc(r.suggested_esi) + '</b>' +
    ' (rules ' + esc(r.rule_esi) + ', AI ' + esc(r.llm_esi || 'n/a') + ')</p>' +
    (r.ai_available == '1' || r.ai_available == 'true'
      ? '<p><b>AI rationale:</b> ' + esc(r.rationale) + '</p>'
      : '<p style="color:#c62828;">AI unavailable. Rule-based ESI only.</p>');
  if (r.assessment) {
    var btn = gel('er_open');
    btn.style.display = 'inline-block';
    btn.onclick = function() {
      top.location.href = 'x_2206627_er_tri_0_triage_assessment.do?sys_id=' + r.assessment;
    };
  }
}

function erFail(msg) {
  clearInterval(erTimer);
  gel('er_running').style.display = 'none';
  var box = gel('er_done');
  box.style.display = 'block';
  box.innerHTML = '';
  var p = document.createElement('p');
  p.style.color = '#c62828';
  p.appendChild(document.createTextNode(msg || 'Triage failed.'));
  box.appendChild(p);
}

function erClose() {
  clearInterval(erTimer);
  GlideModal.prototype.get('x_2206627_er_tri_0_er_triage_progress') ?
    GlideModal.prototype.get('x_2206627_er_tri_0_er_triage_progress').destroy() :
    window.location.reload();
}
